/// <summary>
/// MPJ_28395_Stock reservation
/// Service class <c>METSalesOrderAutoReserveService</c> which is executing the logic for sales line auto reservation
/// </summary>

class METSalesOrderAutoReserveService extends SysOperationServiceBase
{
    METSalesOrderTypeID     metSalesOrderTypeId;
    InventLocationId        inventLocationId;
    Days                    metReserveDaysPriorShipDate;

}

Method.Source:
    /// <summary>
    /// Auto reserve service
    /// </summary>
    /// <param name = "_contract">Instance of the <c>METSalesOrderAutoReserveContract</c> class</param>
    public void processOperation(METSalesOrderAutoReserveContract _contract)
    {
        int                         bundlesize;
        int                         noOfItemIds;
        int                         totalTasks;
        int                         i, j;
        int                         task;

        SalesTable                  salesTable;
        SalesLine                   salesLine;
        MCRHoldCodeTrans            mcrHoldCodeTrans;        
        InventTrans                 inventTrans;
        InventTransOrigin           inventTransOrigin;
        ItemId                      itemId;
        List                        itemIdList          = new List(Types::String);
        List                        itemIdListMain      = new List(Types::String);
        ListEnumerator              itemIdListMainEnumerator;
        METTaskGuid                 batchRunGUID = newGuid();

        BatchHeader         batchHeader = this.getCurrentBatchHeader();

        if (batchHeader == null)
        {
            batchHeader = batchHeader::construct();
        }
        batchHeader.parmCaption("@MET:AutoStockReservation");

        totalTasks      =   _contract.parmTasks();

        totalTasks  = totalTasks <= 0 ? 1 : totalTasks;
        
        task            = 1;
        j               = 0;
        i               = 0;

        metSalesOrderTypeId = _contract.parmMetSalesOrderTypeId();
        inventLocationId    = _contract.parmInventLocationId();
        
        while select ItemId from salesLine group by ItemId
            where salesLine.SalesStatus == SalesStatus::Backorder
                && salesLine.QtyOrdered > 0
            exists join inventTransOrigin
                where inventTransOrigin.InventTransId     == salesLine.InventTransId
                    && inventTransOrigin.ReferenceCategory == InventTransType::Sales
                exists join inventTrans
                    where  inventTransOrigin.RecId == inventTrans.InventTransOrigin
                        && inventTrans.StatusReceipt == StatusReceipt::None
                        &&  inventTrans.StatusIssue   == StatusIssue::OnOrder
            exists join salesTable
                where salesTable.SalesId == salesLine.SalesId
                    && ((metSalesOrderTypeId == '')
                        || (metSalesOrderTypeId != '' && salesTable.METSalesOrderType == metSalesOrderTypeId)) 
                    && ((inventLocationId == '')
                        || (inventLocationId != '' && salesTable.InventLocationId == inventLocationId))
                notexists join mcrHoldCodeTrans
                    where mcrHoldCodeTrans.InventRefId == salesTable.SalesId
                        && mcrHoldCodeTrans.mcrCleared   == NoYes::No
        {
            noOfItemIds++;
            itemIdListMain.addEnd(salesLine.ItemId);
        }        

        bundleSize      =   real2int(roundUp((noOfItemIds / totalTasks), 1.0));

        SysOperationServiceController salesOrderAutoConfirmController = new SysOperationServiceController(
                                                                classStr(METSalesOrderAutoReserveService),
                                                                methodStr(METSalesOrderAutoReserveService, salesOrderAutoConfirmSubTask));

        salesOrderAutoConfirmController.parmDialogCaption("@MET:AutomaticSalesConfirmationFinalTask");
        METSalesOrderAutoReserveContract salesOrderAutoConfirmContract = salesOrderAutoConfirmController.getDataContractObject() as METSalesOrderAutoReserveContract;
        salesOrderAutoConfirmContract.parmBatchRunGUID(batchRunGUID);

        batchHeader.addRuntimeTask(salesOrderAutoConfirmController, this.getCurrentBatchTask().RecId);

        itemIdListMainEnumerator    = itemIdListMain.getEnumerator();

        while (itemIdListMainEnumerator.moveNext())
        {

            itemId = itemIdListMainEnumerator.current();
            
            i++;
            j++;

            itemIdList.addEnd(itemId);

            if(i == bundlesize || j == noOfItemIds)
            {
                SysOperationServiceController salesOrderAutoReserveController = new SysOperationServiceController(
                                                                classStr(METSalesOrderAutoReserveService),
                                                                methodStr(METSalesOrderAutoReserveService, salesOrderAutoReserveSubTask));

                salesOrderAutoReserveController.parmDialogCaption(strFmt("@MET:AutomaticSalesConfirmationSubTask", task));

                METSalesOrderAutoReserveContract salesOrderAutoReserveContract = salesOrderAutoReserveController.getDataContractObject() as METSalesOrderAutoReserveContract;
                salesOrderAutoReserveContract.parmItemIdList(itemIdList);
                salesOrderAutoReserveContract.parmBatchRunGUID(batchRunGUID);

                batchHeader.addRuntimeTask(salesOrderAutoReserveController, this.getCurrentBatchTask().RecId);
                batchHeader.addDependency(salesOrderAutoConfirmController, salesOrderAutoReserveController, BatchDependencyStatus::FinishedOrError);

                itemIdList = new List(Types::String);
                task++;
                i = 0;
            }
        }

        batchHeader.save();     
    }

    /// <summary>
    /// Sales order auto reserve
    /// </summary>
    /// <param name = "_contract">Instance of the <c>METSalesOrderAutoReserveContract</c> class</param>
    public void salesOrderAutoReserveSubTask(METSalesOrderAutoReserveContract _contract)
    {
        SalesTable                      salesTable;
        SalesLine                       salesLine;
        MCRHoldCodeTrans                mcrHoldCodeTrans;
        InventTrans                     inventTrans;
        InventTransOrigin               inventTransOrigin;        
        METSalesPurchLineShipDateTmp    salesLineShipDateTmp;
        SalesParameters                 salesParameters = SalesParameters::find();
        ItemId                          itemId;
        ListEnumerator                  itemIdListEnumerator;
        date                            reserveDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) + salesParameters.METReserveDaysPriorShipDate;
        
        metReserveDaysPriorShipDate = _contract.parmMETReserveDaysPriorShipDate();
        
        itemIdListEnumerator        = _contract.parmItemIdList().getEnumerator();

        while (itemIdListEnumerator.moveNext())
        {
            itemId = itemIdListEnumerator.current();

            ttsbegin;

            if (salesParameters.METAutoReserveDateSequence == METAutoReserveDateSequence::RequestedShipDate)
            {
                insert_recordset salesLineShipDateTmp (RefRecId, ShippingDate)
                select RecId, ShippingDateConfirmed from salesLine
                    where salesLine.SalesStatus == SalesStatus::Backorder
                        && salesLine.QtyOrdered > 0
                        && salesLine.ShippingDateConfirmed != dateNull()
                        && salesLine.ItemId == itemId
                    exists join salesTable
                        where salesTable.SalesId == salesLine.SalesId
                            && ((inventLocationId == '')
                                || (inventLocationId != '' && salesTable.InventLocationId == inventLocationId))
                        notexists join mcrHoldCodeTrans
                            where mcrHoldCodeTrans.InventRefId == salesTable.SalesId
                                && mcrHoldCodeTrans.mcrCleared   == NoYes::No;

                insert_recordset salesLineShipDateTmp (RefRecId, ShippingDate)
                select RecId, ShippingDateRequested from salesLine
                    where salesLine.SalesStatus == SalesStatus::Backorder
                        && salesLine.QtyOrdered > 0
                        && salesLine.ShippingDateConfirmed == dateNull()
                        && salesLine.ItemId == itemId
                    exists join salesTable
                        where salesTable.SalesId == salesLine.SalesId
                            && ((inventLocationId == '')
                                || (inventLocationId != '' && salesTable.InventLocationId == inventLocationId))
                        notexists join mcrHoldCodeTrans
                            where mcrHoldCodeTrans.InventRefId == salesTable.SalesId
                                && mcrHoldCodeTrans.mcrCleared   == NoYes::No;
        
                while select salesLine order by salesLineShipDateTmp.ShippingDate
                    where salesLine.SalesStatus == SalesStatus::Backorder
                        && salesLine.QtyOrdered > 0
                        && salesLine.ItemId == itemId
                    join salesLineShipDateTmp
                        where salesLineShipDateTmp.RefRecId == salesLine.RecId
                            && ((salesLine.Reservation != ItemReservation::None)
                                || ((salesLine.Reservation == ItemReservation::None) 
                                && (salesLineShipDateTmp.ShippingDate  <= reserveDate)))
                    join RecId from inventTransOrigin
                            where inventTransOrigin.InventTransId     == salesLine.InventTransId
                                && inventTransOrigin.ReferenceCategory == InventTransType::Sales
                        join inventTrans
                            where  inventTransOrigin.RecId == inventTrans.InventTransOrigin
                                && inventTrans.StatusReceipt == StatusReceipt::None
                                &&  inventTrans.StatusIssue   == StatusIssue::OnOrder
                    join RecId from salesTable
                        where salesTable.SalesId == salesLine.SalesId
                            && ((inventLocationId == '')
                                || (inventLocationId != '' && salesTable.InventLocationId == inventLocationId))
                        notexists join mcrHoldCodeTrans
                            where mcrHoldCodeTrans.InventRefId == salesTable.SalesId
                                && mcrHoldCodeTrans.mcrCleared   == NoYes::No
                {
                    this.reserve(salesLine, inventTrans, _contract.parmBatchRunGUID());                   
                }
            }

            else if (salesParameters.METAutoReserveDateSequence == METAutoReserveDateSequence::OrderDate)
            {
                while select salesLine order by salesLine.CreatedDateTime
                    where salesLine.SalesStatus == SalesStatus::Backorder
                        && salesLine.QtyOrdered > 0
                        && salesLine.ItemId == itemId
                    join RecId from inventTransOrigin
                            where inventTransOrigin.InventTransId     == salesLine.InventTransId
                                && inventTransOrigin.ReferenceCategory == InventTransType::Sales
                        join inventTrans
                            where  inventTransOrigin.RecId == inventTrans.InventTransOrigin
                                && inventTrans.StatusReceipt == StatusReceipt::None
                                &&  inventTrans.StatusIssue   == StatusIssue::OnOrder
                    join RecId from salesTable
                        where salesTable.SalesId == salesLine.SalesId
                            && ((inventLocationId == '')
                                || (inventLocationId != '' && salesTable.InventLocationId == inventLocationId))
                        notexists join mcrHoldCodeTrans
                            where mcrHoldCodeTrans.InventRefId == salesTable.SalesId
                                && mcrHoldCodeTrans.mcrCleared   == NoYes::No
                {
                    this.reserve(salesLine, inventTrans, _contract.parmBatchRunGUID());
                }

            }    
            
            ttscommit;
        }
    }

    /// <summary>
    /// Sales order auto confirm
    /// </summary>
    /// <param name = "_contract">Instance of the <c>METSalesOrderAutoReserveContract</c> class</param>
    /// 
    public void salesOrderAutoConfirmSubTask(METSalesOrderAutoReserveContract _contract)
    {
        SalesTable                      salesTable;        
        METSalesIdTmp                   metSalesIdTmp;        
        METTaskGuid                     batchRunGUID    = _contract.parmBatchRunGUID();
        SalesFormLetter_Confirm         confirm;

        while select metSalesIdTmp group by SalesId
            where metSalesIdTmp.BatchRunGuid == batchRunGUID
            join salesTable
                where metSalesIdTmp.SalesId == salesTable.SalesId
        {
            METSalesIdTmp                   metSalesIdTmpComplete;

            select firstonly metSalesIdTmpComplete
                where metSalesIdTmpComplete.SalesId == metSalesIdTmp.SalesId
                    && metSalesIdTmpComplete.BatchRunGuid == batchRunGUID
                    && metSalesIdTmpComplete.IsSubstituted == NoYes::Yes;
            
            if (metSalesIdTmpComplete.RecId)
            {
                RetailSalesTable retailSales = salesTable.retailSalesTable();
                RetailSalesOrderCalculator::setPricesDiscountsAndDateTypeOnOrderOnServer(salesTable.SalesId, retailSales.TotalManualDiscountPercentage, SalesPriceDateType::Today);
                
                MCREndOrder::orderRecapForExternalGiftCard(salesTable);
                if (salesTable.useUnifiedPricingEngine())
                {
                    salesTable.lockPriceForRetailOrder();
                }

                GUPParameters gupParameters = GUPParameters::find();
                if (gupParameters.AutoConfirmSalesOrderWithComplete)
                {
                    confirm = SalesFormLetter::construct(DocumentStatus::Confirmation);

                    confirm.update( salesTable,
                                    DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                    SalesUpdate::All);
                }
            }
        }

        delete_from metSalesIdTmp
            where metSalesIdTmp.BatchRunGuid == batchRunGUID;
    }

    /// <summary>
    /// Reserve sales line quantity
    /// </summary>
    /// <param name = "_inventTrans">InventTrans</param>   
    /// <returns>Success/Failure</returns>
    public boolean reserveSalesQty(InventTrans _inventTrans)
    {
        InventMovement                  inventMovement;
        InventUpd_Reservation           inventUpd_Reservation;
        boolean                         ret = false;

        if (_inventTrans)
        {
            try
            {
                Inventmovement        = _inventTrans.inventmovement(true);
                inventUpd_Reservation = InventUpd_Reservation::newInventDim(inventmovement, _inventTrans.inventDim(), _inventTrans.Qty, false);
                inventUpd_Reservation.updatenow();
                ret = inventUpd_Reservation.parmReservationFailed() ? false : true;
            }
            catch
            {
                ret = false;
            }
        }

        return ret;
    }

    /// <summary>
    /// Reserves sales quantity
    /// </summary>
    /// <param name = "_salesLine">Sales line</param> 
    /// <param name = "_inventTrans">InventTrans</param>
    /// <param name = "_batchRunGUID">BatchRunGUID</param>
    
    public void reserve(SalesLine _salesLine, InventTrans   _inventTrans, METTaskGuid     _batchRunGUID)
    {
        SalesLine       salesLineSubs       = SalesLine::findInventTransId(_salesLine.InventTransId);
        METSalesLine    metSalesLineSubs    = METSalesLine::find(salesLineSubs.RecId);
        boolean         ret = false;
        METSalesIdTmp   metSalesIdTmp;        

        SalesLine   newSalesLine    = this.applySubstitution(salesLineSubs, metSalesLineSubs, salesLineSubs.inventDim());

        if (newSalesLine)
        {
            InventTrans             inventTransNew;
            InventTransOrigin       inventTransOriginNew;

            select firstonly metSalesIdTmp
                where metSalesIdTmp.SalesId == _salesLine.SalesId
                    && metSalesIdTmp.BatchRunGuid == _batchRunGUID
                    && metSalesIdTmp.IsSubstituted == NoYes::Yes;

            if (!metSalesIdTmp)
            {
                metSalesIdTmp.SalesId       = _salesLine.SalesId;
                metSalesIdTmp.BatchRunGuid  = _batchRunGUID;
                metSalesIdTmp.IsSubstituted = NoYes::Yes;
                metSalesIdTmp.insert();
            }

            select inventTransNew
                where  inventTransNew.StatusReceipt == StatusReceipt::None
                    &&  inventTransNew.StatusIssue   == StatusIssue::OnOrder
                exists join inventTransOriginNew
                    where inventTransOriginNew.RecId == inventTransNew.InventTransOrigin
                        && inventTransOriginNew.InventTransId     == newSalesLine.InventTransId
                        && inventTransOriginNew.ReferenceCategory == InventTransType::Sales;

            if (inventTransNew)
            {
                ret = this.reserveSalesQty(inventTransNew);
            }
        }
        else
        {
            ret = this.reserveSalesQty(_inventTrans);
        }

        if (ret)
        {
            select firstonly metSalesIdTmp
                where metSalesIdTmp.SalesId == _salesLine.SalesId
                    && metSalesIdTmp.BatchRunGuid == _batchRunGUID;

            if (!metSalesIdTmp)
            {
                metSalesIdTmp.SalesId       = _salesLine.SalesId;
                metSalesIdTmp.BatchRunGuid  = _batchRunGUID;
                metSalesIdTmp.insert();
            }
        }
    }

    /// <summary>
    /// check substitute
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <param name = "_metSalesLine">_metSalesLine</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns>Sales line</returns>
    public SalesLine applySubstitution(SalesLine       _salesLine,
                                       METSalesLine    _metSalesLine,
                                       InventDim       _inventDim)
    {
        METSalesItemSubstitution    metSalesItemSubstitution = METSalesItemSubstitution::construct();
        SalesLine                   salesLine;
        SalesTable                  salesTable  = _salesLine.salesTable();

        if (salesTable.metSubstitutionActive())
        {
            InventQty           inventQty;
            InventTrans         inventTrans;
            InventTransOrigin   inventTransOrigin;
           
            select sum(Qty) from inventTrans
                exists join inventTransOrigin
                    where inventTrans.InventTransOrigin == inventTransOrigin.RecId &&
                          inventTransOrigin.InventTransId == _salesLine.InventTransId &&
                          inventTrans.StatusReceipt == StatusReceipt::None &&
                          inventTrans.StatusIssue   == StatusIssue::OnOrder;

            inventQty = - inventTrans.Qty;

            if (inventQty > 0 && inventQty == _salesLine.QtyOrdered)
            {
                Qty         qtyOnHand   = metSalesItemSubstitution.queryOnHandQty(_salesLine.ItemId, _inventDim);

                if(qtyOnHand <= 0 && qtyOnHand < _salesLine.QtyOrdered)
                {
                    boolean found   = metSalesItemSubstitution.findSubstitutionItem(_salesLine.ItemId,
                                                                                    _inventDim,
                                                                                    salesTable.CustAccount,
                                                                                    salesTable.custTable_CustAccount().CustGroup,
                                                                                    _salesLine.QtyOrdered,
                                                                                    true,
                                                                                    false);

                    METSalesLine    metSalesLineSub    = metSalesItemSubstitution.parmMetSalesLine();

                    if (found && metSalesLineSub.SubstituteReplacementItemID != '' &&
                    _salesLine.ItemId != metSalesLineSub.SubstituteReplacementItemID)
                    {
                        salesLine   = metSalesItemSubstitution.copyToNewLine(_salesLine, metSalesLineSub);
                    }
                }
            }
           
        }

        return (salesLine.RecId && (_salesLine.RecId != salesLine.RecId)) ? salesLine : null;
    }
